                      {tool.icon}
                    </div>
                  </div>
                </div>

                <div className={`w-10 h-10 rounded-xl ${tool.iconBg} flex items-center justify-center mb-4`}>
                  {tool.icon}
                </div>
                <h3 className="font-display font-bold text-xl text-primary mb-2">{tool.title}</h3>
                <p className="text-muted text-sm leading-relaxed">{tool.description}</p>
              </div>
            </Reveal>
          ))}
        </div>
      </div>
    </section>
  )
}

function TestimonialCard({ testimonial }: { testimonial: typeof testimonials[0] }) {
  return (
    <div className="w-80 md:w-96 flex-shrink-0 mx-3">
      <div className="bg-white rounded-2xl p-6 border border-border-light shadow-sm h-full hover:shadow-md transition-shadow">
        <div className="flex items-center gap-3 mb-4">
          <div
            className="w-10 h-10 rounded-full flex items-center justify-center text-white font-bold text-sm"
            style={{ backgroundColor: testimonial.color }}
          >
            {testimonial.name[0]}
          </div>
          <div>
            <div className="font-semibold text-sm text-primary">{testimonial.name}</div>
            {testimonial.company && (
              <div className="text-xs text-muted">{testimonial.company}</div>
            )}
          </div>
        </div>
        <p className="text-sm text-muted leading-relaxed">{testimonial.text}</p>
      </div>
    </div>
  )
}

function Testimonials() {
  const row1 = [...testimonials.slice(0, 3), ...testimonials.slice(0, 3), ...testimonials.slice(0, 3), ...testimonials.slice(0, 3)]
  const row2 = [...testimonials.slice(3), ...testimonials.slice(3), ...testimonials.slice(3), ...testimonials.slice(3)]

  return (
    <section className="py-20 md:py-28 bg-surface overflow-hidden">
      <div className="max-w-6xl mx-auto px-6">
        <Reveal>
          <div className="text-center mb-14">
            <h2 className="font-display font-bold text-3xl md:text-5xl tracking-tight text-primary mb-4">
              What our users are saying.
            </h2>
            <p className="text-muted text-lg max-w-xl mx-auto">
              Trusted by thousands of designers and teams worldwide.
            </p>
          </div>
        </Reveal>
      </div>

      {/* Row 1 - scrolls left */}
      <div className="mb-6 overflow-hidden">
        <div className="flex marquee-left-fast w-max">
          {row1.map((t, i) => (
            <TestimonialCard key={`r1-${i}`} testimonial={t} />
          ))}
        </div>
      </div>

      {/* Row 2 - scrolls right */}
      <div className="overflow-hidden">
        <div className="flex marquee-right-fast w-max">
          {row2.map((t, i) => (
            <TestimonialCard key={`r2-${i}`} testimonial={t} />
          ))}
        </div>
      </div>
    </section>
  )
}

function BrandIcon({ brand }: { brand: typeof ctaBrands[0] }) {
  return (
    <div className="flex-shrink-0 mx-3 md:mx-4">
      <div
        className="w-12 h-12 md:w-14 md:h-14 rounded-2xl flex items-center justify-center shadow-sm border border-border-light"
        style={{ backgroundColor: brand.color + '15' }}
      >
        <span
          className="font-display font-bold text-sm md:text-base"
          style={{ color: brand.color === '#141414' ? '#141414' : brand.color }}
        >
          {brand.name.slice(0, 2)}
        </span>
      </div>
    </div>
  )
}

function CTASection() {
  const row1Brands = [...ctaBrands.slice(0, 8), ...ctaBrands.slice(0, 8), ...ctaBrands.slice(0, 8), ...ctaBrands.slice(0, 8)]
  const row2Brands = [...ctaBrands.slice(8), ...ctaBrands.slice(8), ...ctaBrands.slice(8), ...ctaBrands.slice(8)]

  return (
    <section className="py-20 md:py-28 overflow-hidden">
      <div className="max-w-4xl mx-auto px-6 text-center mb-14">
        <Reveal>
          <h2 className="font-display font-bold text-3xl md:text-5xl tracking-tight text-primary mb-6">
            Never run out of<br />inspiration again.
          </h2>
        </Reveal>
        <Reveal delay={0.08}>
          <p className="text-muted text-lg max-w-xl mx-auto mb-10">
            Use ScreenVault for free as long as you like or get full access with any of our paid plans.
          </p>
        </Reveal>
        <Reveal delay={0.16}>
          <div className="flex flex-col sm:flex-row items-center justify-center gap-4">
            <a href="#" className="w-full sm:w-auto bg-accent hover:bg-accent-hover text-white font-semibold px-8 py-3.5 rounded-full text-base transition-all duration-200 hover:shadow-lg hover:shadow-accent/25">
              Join for free
            </a>
            <a href="#" className="w-full sm:w-auto border-2 border-border text-primary font-semibold px-8 py-3.5 rounded-full text-base hover:border-muted transition-all duration-200 flex items-center justify-center gap-2 group">
              See our plans
              <ArrowRight className="w-4 h-4 transition-transform group-hover:translate-x-0.5" />
            </a>
          </div>
        </Reveal>
      </div>

      {/* Brand marquee row 1 */}
      <div className="mb-4 overflow-hidden">
        <div className="flex marquee-left w-max">
          {row1Brands.map((b, i) => (
            <BrandIcon key={`cta1-${i}`} brand={b} />
          ))}
        </div>
      </div>

      {/* Brand marquee row 2 - opposite direction */}
      <div className="overflow-hidden">
        <div className="flex marquee-right w-max">
          {row2Brands.map((b, i) => (
            <BrandIcon key={`cta2-${i}`} brand={b} />
          ))}
        </div>
      </div>
    </section>
  )
}

function Footer() {
  const footerLinks = {
    Explore: [
      { label: 'Glossary', href: '#' },
      { label: 'Pricing', href: '#' },
      { label: 'Changelog', href: '#' },
      { label: 'Blog', href: '#' },
      { label: 'Colors', href: '#' },
    ],
    Contact: [
      { label: 'Help center', href: '#' },
      { label: 'Careers', href: '#' },
      { label: 'Merch', href: '#' },
      { label: 'Support', href: '#' },
    ],
    Social: [
      { label: 'X (Twitter)', href: '#' },
      { label: 'LinkedIn', href: '#' },
    ],
  }

  return (
    <footer className="bg-primary text-white">
      <div className="max-w-7xl mx-auto px-6 py-16 md:py-20">
        <div className="grid grid-cols-1 md:grid-cols-12 gap-12">
          {/* Brand */}
          <div className="md:col-span-4">
            <div className="flex items-center gap-2.5 mb-4">
              <div className="w-8 h-8 bg-gradient-to-br from-accent to-violet rounded-lg flex items-center justify-center">
                <svg className="w-4.5 h-4.5 text-white" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                  <rect x="2" y="3" width="20" height="14" rx="2" />
                  <path d="M8 21h8M12 17v4" />
                </svg>
              </div>
              <span className="font-display font-bold text-lg">ScreenVault</span>
            </div>
            <p className="text-white/50 text-sm leading-relaxed max-w-xs">
              Design better digital experiences with ScreenVault.
            </p>
          </div>

          {/* Links */}
          {Object.entries(footerLinks).map(([title, links]) => (
            <div key={title} className="md:col-span-2">
              <h4 className="font-semibold text-sm text-white/40 uppercase tracking-wider mb-4">{title}</h4>
              <ul className="space-y-3">
                {links.map(link => (
                  <li key={link.label}>
                    <a href={link.href} className="text-sm text-white/60 hover:text-white transition-colors">
                      {link.label}
                    </a>
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>

        {/* Bottom bar */}
        <div className="mt-16 pt-8 border-t border-white/10 flex flex-col md:flex-row items-center justify-between gap-4">
          <p className="text-xs text-white/30">
            &copy; ScreenVault 2018–2026. All rights reserved.
          </p>
          <div className="flex items-center gap-6">
            <a href="#" className="text-xs text-white/30 hover:text-white/60 transition-colors">Privacy Policy</a>
            <a href="#" className="text-xs text-white/30 hover:text-white/60 transition-colors">Terms</a>
          </div>
        </div>
      </div>
    </footer>
  )
}

// ─── App ──────────────────────────────────────────────────────────────────────

export default function App() {
  return (
    <div className="min-h-screen bg-white">
      <AnnouncementBar />
      <Header />
      <main>
        <Hero />
        <TrustedBy />
        <Stats />
        <FeaturesSearch />
        <FeaturesFlows />
        <FeaturesTools />
        <Testimonials />
        <CTASection />
      </main>
      <Footer />
    </div>
  )
}

